<?php
declare(strict_types=1);
namespace Banklord;

/**
 * Resolves the FileDataID that the game client reports for a bank slot texture
 * to its icon name (wowdev/wow-listfile, verified entries under Interface/Icons).
 * Data: src/icon-filedata.tsv.gz, generated by dev/tools/build_icon_map.py (no images).
 */
final class IconMap {
    private static ?array $map=null;
    public const NAME_PATTERN='/^[a-z0-9][a-z0-9_-]{0,79}$/D';
    /** Textures the client shows while item data is not cached yet; never authoritative. */
    private const PLACEHOLDERS=['temp','inv_misc_questionmark'];

    public static function name(mixed $fileID): ?string {
        if (is_string($fileID) && ctype_digit($fileID)) $fileID=(int)$fileID;
        if (!is_int($fileID) || $fileID<1 || $fileID>4294967295) return null;
        if (self::$map===null) {
            self::$map=[];
            $raw=@file_get_contents(__DIR__.'/icon-filedata.tsv.gz');
            $tsv=is_string($raw) ? @gzdecode($raw) : false;
            if (is_string($tsv)) {
                foreach (explode("\n",$tsv) as $line) {
                    $tab=strpos($line,"\t");
                    if ($tab!==false) self::$map[(int)substr($line,0,$tab)]=substr($line,$tab+1);
                }
            }
        }
        $name=self::$map[$fileID]??null;
        if (!is_string($name) || in_array($name,self::PLACEHOLDERS,true)) return null;
        return preg_match(self::NAME_PATTERN,$name) ? $name : null;
    }

    public static function url(string $name): ?string {
        $name=strtolower(trim($name));
        if (!preg_match(self::NAME_PATTERN,$name)) return null;
        return 'https://wow.zamimg.com/images/wow/icons/medium/'.$name.'.jpg';
    }
}
